/* ===== BEGIN v018-update.js ===== */


(function(){
  'use strict';
  const q=s=>document.querySelector(s);
  const esc=v=>typeof window.escHtml==='function'?window.escHtml(String(v??'')):String(v??'');

  // ================================================================
  // 1) CONTEXT GUARD — class / expansion specific windows never leak
  // ================================================================
  function currentCtx(){
    return {
      cls:String(window.currentClass||document.getElementById('char-class')?.value||'').trim(),
      nature:String(window.currentNature||document.getElementById('char-nature')?.value||'').trim()
    };
  }
  function setVisible(ids, visible){ ids.forEach(id=>{const el=q(id); if(el) el.style.display=visible?'':'none';}); }
  function clearStaleSpecificContent(cls){
    const host=q('#specific-content-container'); if(!host) return;
    const staleMerc=host.querySelector('.death-market-head, .v17-market-shell, .v16-merchant-grid');
    const staleEso=host.querySelector('.eso-surgery-suite, .v16-esoteric-surgery, .v16-surgery-header');
    if(cls!=='Mercador da Morte' && staleMerc) host.innerHTML='';
    if(cls!=='Esotérico' && staleEso) host.innerHTML='';
  }
  function enforceContext(){
    const {cls,nature}=currentCtx();
    setVisible(['#btn-tab-alquerino','#tab-alquerino'], cls==='Alquerino');
    setVisible(['#btn-tab-rituals','#tab-rituals'], cls==='Hermético');
    clearStaleSpecificContent(cls);
    // Never leave a hidden, foreign dynamic tab active.
    // O estado de seleção da aba é representado pelo .tab-content.active, não
    // necessariamente pelo botão, porque openTab() historicamente não marca
    // botões dinâmicos como ativos. Não redirecione apenas por ausência de
    // .tab-btn.active: o Códice Hermético pode estar corretamente aberto.
    const activeTab=document.querySelector('.tab-content.active');
    const activeTabId=activeTab?.id || '';
    const isForeignHiddenDynamic = activeTabId === 'tab-alquerino' && q('#btn-tab-alquerino')?.style.display === 'none'
      || activeTabId === 'tab-rituals' && q('#btn-tab-rituals')?.style.display === 'none'
      || activeTabId === 'tab-specific' && !q('#btn-tab-specific');
    if(isForeignHiddenDynamic && typeof window.openTab==='function') window.openTab('tab-identity');
  }

  const wrapHook=(name)=>{
    const prev=window[name];
    if(typeof prev!=='function' || prev.__v18Wrapped) return;
    const wrapped=function(){
      const r=prev.apply(this,arguments);
      setTimeout(enforceContext,0);
      return r;
    };
    wrapped.__v18Wrapped=true; window[name]=wrapped;
  };
  // toggleEditUI é uma operação genérica de edição e não altera o contexto da ficha.
  // Mantê-lo fora deste guard evita que mudanças locais (como Conhecido/Sintonizado
  // no Códice Hermético) provoquem navegação de aba.
  ['selectClass','selectNature','initBuilderForSelectedMode','loadCharacterToBuilder'].forEach(wrapHook);
  document.addEventListener('DOMContentLoaded',()=>setTimeout(enforceContext,120));

  // ================================================================
  // 2) MERCADO DA MORTE — stable, non-overlapping operational panel
  // ================================================================
  const style=document.createElement('style');
  style.id='v018-styles';
  style.textContent=`
    .v18-market-stable{display:grid;gap:14px;clear:both;position:relative;isolation:isolate}
    .v18-market-head{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:start;padding:14px 16px;border:1px solid rgba(214,140,69,.20);border-radius:13px;background:linear-gradient(145deg,rgba(40,22,12,.72),rgba(11,8,7,.94));overflow:hidden}
    .v18-market-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
    .v18-kpi{min-width:0;padding:10px;border:1px solid rgba(214,140,69,.18);border-radius:9px;background:rgba(0,0,0,.18);box-sizing:border-box}
    .v18-kpi span{display:block;color:#8e7a6b;font-size:.66rem;text-transform:uppercase;letter-spacing:.08em}
    .v18-kpi b{display:block;color:#f0c68d;font:700 1rem/1.2 Cinzel,serif;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
    .v18-market-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px!important;align-items:start!important}
    .v18-market-grid>*{min-width:0;max-width:100%;box-sizing:border-box;position:relative!important;float:none!important;transform:none!important}
    .v18-market-section{min-height:0!important;overflow:hidden!important}
    @media(max-width:900px){.v18-market-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.v18-market-grid{grid-template-columns:1fr!important}}
    @media(max-width:560px){.v18-market-kpis{grid-template-columns:1fr}}
  `;
  document.head.appendChild(style);

  // ================================================================
  // 5) MARKET GRID HARDENING
  // ================================================================
  function stabilizeMarket(){
    const host=q('#specific-content-container'); if(!host||currentCtx().cls!=='Mercador da Morte')return;
    const head=host.querySelector('.death-market-head'); const modules=[...host.querySelectorAll('.death-module, .v16-death-module, .v14-death-module')];
    if(!head)return;
    let shell=host.querySelector('.v18-market-stable');
    if(!shell){
      shell=document.createElement('div'); shell.className='v18-market-stable';
      head.parentNode.insertBefore(shell,head); shell.appendChild(head);
      const k=host.querySelector('.v17-market-kpis,.v18-market-kpis'); if(k)shell.appendChild(k);
      const grid=document.createElement('div'); grid.className='v18-market-grid';
      modules.forEach(m=>grid.appendChild(m));
      shell.appendChild(grid);
    }else{
      const grid=shell.querySelector('.v18-market-grid'); if(grid)modules.forEach(m=>{if(m.parentElement!==grid)grid.appendChild(m)});
    }
    shell.classList.add('v18-market-stable');
  }
  const oldMMRender=window.renderMerc16;
  if(typeof oldMMRender==='function' && !oldMMRender.__marketStabilized){
    const wrapped=function(){const r=oldMMRender.apply(this,arguments);setTimeout(stabilizeMarket,0);return r;};
    wrapped.__marketStabilized=true;
    window.renderMerc16=wrapped;
  }

  setTimeout(()=>{enforceContext();stabilizeMarket();},260);
})();

/* ===== END v018-update.js ===== */

