/* ===== CONSOLIDATED FIX — Skill Tree real binding + Treino/Arsenal layout ===== */
(function(){
  'use strict';
  const $ = selector => document.querySelector(selector);
  const marketStyle=document.createElement('style');
  marketStyle.id='mundos-consolidated-market-fix';
  marketStyle.textContent=`
    /* Treino & Arsenal: o legado da natureza não disputa espaço com o painel operacional. */
    #specific-content-container.mercador-layout-stable{display:block!important;position:relative!important;clear:both!important;overflow:visible!important}
    #specific-content-container.mercador-layout-stable > .form-group.legacy-mercador-field{display:none!important}
    #specific-content-container.mercador-layout-stable .death-market-panel{position:relative!important;inset:auto!important;float:none!important;transform:none!important;width:100%!important;max-width:100%!important;box-sizing:border-box!important;clear:both!important}
    #specific-content-container.mercador-layout-stable .death-market-grid{position:relative!important;display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;gap:14px!important;align-items:start!important;clear:both!important}
    #specific-content-container.mercador-layout-stable .death-module{position:relative!important;inset:auto!important;float:none!important;transform:none!important;width:auto!important;max-width:none!important;min-width:0!important;box-sizing:border-box!important;overflow:hidden!important}
    #specific-content-container.mercador-layout-stable .v16-arsenal-module{grid-column:auto!important}
    @media(max-width:820px){#specific-content-container.mercador-layout-stable .death-market-grid{grid-template-columns:1fr!important}}
  `;
  document.head.appendChild(marketStyle);

  function stabilizeMercadorLayout(){
    const host=$('#specific-content-container');
    if(!host || String(window.currentClass||'')!=='Mercador da Morte') return;
    host.classList.add('mercador-layout-stable');
    // The old natureData.tabHtml contains only the pre-v13 Patamar/Arsenal fields.
    // The operational Mercado panel supersedes them; keeping both is what caused overlap.
    [...host.children].forEach(el=>{
      if(el.id==='death-market-panel' || el.classList.contains('v18-market-stable') || el.classList.contains('death-market-head')) return;
      if(el.classList.contains('form-group')) el.classList.add('legacy-mercador-field');
    });
    const panel=host.querySelector('#death-market-panel');
    if(panel){ panel.style.position='relative'; panel.style.inset='auto'; panel.style.float='none'; panel.style.transform='none'; }
  }

  const oldMerc=window.renderMerc16;
  if(typeof oldMerc==='function' && !oldMerc.__consolidatedFix){
    const wrapped=function(){
      const r=oldMerc.apply(this,arguments);
      setTimeout(stabilizeMercadorLayout,0);
      return r;
    };
    wrapped.__consolidatedFix=true;
    window.renderMerc16=wrapped;
  }
  const oldSelect=window.selectClass;
  if(typeof oldSelect==='function' && !oldSelect.__consolidatedMerc){
    const wrapped=function(){const r=oldSelect.apply(this,arguments);setTimeout(stabilizeMercadorLayout,0);return r;};
    wrapped.__consolidatedMerc=true;window.selectClass=wrapped;
  }
  document.addEventListener('click',e=>{if(e.target.closest('#specific-content-container .death-market-panel'))setTimeout(stabilizeMercadorLayout,10)},true);
  setTimeout(stabilizeMercadorLayout,350);
})();
